/bin/bash -lc "python - <<'PY'
from sim import Sim
import numpy as np

def test(label, mods):
    sim=Sim(); c=sim.home_ctrl()
    for i,v in mods.items(): c[i]=v
    xs=[]
    for t in range(600):
        sim.data.ctrl[:]=c
        sim.step()
        if t%100==0:
            p=sim.pelvis_position(); xs.append((t,float(p[0]),float(p[2]),float(sim.torso_up())))
    print(label, xs, 'final', sim.pelvis_position(), sim.torso_up())

for hp in [-0.4,-0.2,0.0,0.2]:
    test(f'hips {hp}', {2:hp,7:hp})
for kp in [0.8,1.0,1.2,1.4]:
    test(f'knees {kp}', {3:kp,8:kp})
for hp,kp in [(-0.2,1.0),(0.0,1.2),(0.2,1.4),(0.2,1.2)]:
    test(f'combo {hp} {kp}', {2:hp,7:hp,3:kp,8:kp})
PY"

